function readNumbers(text) {
  return text.split(",").map((part) => Number(part));
}

function sum(numbers) {
  let total = 0;
  for (const number of numbers) {
    total += number;
  }
  return total;
}

console.log(sum(readNumbers("1,2,3")));

function readNumbers(text) {
  return text.split(",").map((part) => Number(part));
}

function add(values) {
  let result = 0;
  for (const value of values) {
    result += value;
  }
  return result;
}

console.log(add(readNumbers("4,5,6")));
